// MARK: - Snapping

/// Spec §4.4's snapping, as one value a gesture can consult.
///
/// Candidates are the core's (`ReelProject.snapCandidates(excluding:)` —
/// every other clip's edges and the markers) plus the playhead and the
/// in/out points, which the core does not know about because they are view
/// state. `enabled` folds together the N toggle and the ⌘ suppression, so a
/// session never has to look at modifier flags itself.
struct TimelineSnapper {
    let fps: Fps
    let candidates: [Ticks]
    /// Radius in ticks — `TimelineLayout.snapThreshold`, i.e. 8 points.
    let threshold: Ticks
    let enabled: Bool

    /// The time to actually use, and the guide to draw (nil when nothing
    /// was snapped). A candidate is already on the frame grid, so only the
    /// unsnapped case needs `snapToFrame` — but every tick that reaches an
    /// op leaves here on the grid either way (spec §6).
    func resolve(_ time: Ticks) -> (time: Ticks, guide: Ticks?) {
        guard enabled else { return (ReelTime.snapToFrame(time, fps: fps), nil) }
        let (resolved, snapped) = ReelSnap.resolve(candidates, time, threshold: threshold)
        if snapped { return (resolved, resolved) }
        return (ReelTime.snapToFrame(time, fps: fps), nil)
    }

    /// The candidate list for a gesture that must not snap to the very clips
    /// it is moving. `core` comes from `snapCandidates(excluding:)`.
    static func candidates(
        core: [Ticks], playhead: Ticks, range: (start: Ticks, end: Ticks)?
    ) -> [Ticks] {
        var all = core
        all.append(playhead)
        if let range = range {
            all.append(range.start)
            all.append(range.end)
        }
        return Array(Set(all)).sorted()
    }
}

    mutating func update(time: Ticks, snapper: TimelineSnapper) {
        let resolved = snapper.resolve(time)
        self.time = max(earliest, min(resolved.time, latest))
        guide = resolved.guide
        didMove = true
    }
}

// MARK: - Marquee

/// Rubber-band selection from empty timeline space — a lane's gap, or the
/// room above the first lane and below the last (`TimelineHit.lane` and
/// `.outside`). ⇧ adds to what was already selected; a bare drag replaces it.
struct RangeSession {
    let origin: CGPoint
    let additive: Bool
    let base: Set<UInt32>
    var current: CGPoint

    var rect: CGRect {
        CGRect(
            x: min(origin.x, current.x), y: min(origin.y, current.y),
            width: abs(current.x - origin.x), height: abs(current.y - origin.y))
    }

    /// Every clip whose bar intersects the band, unioned with `base` when ⇧
    /// was held. Locked tracks are skipped: a marquee that selects clips no
    /// edit can touch is a trap.
    func selection(in snapshot: ProjectSnapshot, layout: TimelineLayout) -> Set<UInt32> {
        var hit = additive ? base : []
        let band = rect
        for (index, track) in snapshot.tracks.enumerated() where !track.locked {
            let row = layout.row(forTrackIndex: index)
            for clip in snapshot.clips(onTrack: track.id)
            where layout.clipRect(clip, row: row).intersects(band) {
                hit.insert(clip.id)
            }
        }
        return hit
    }
}

// MARK: - Playhead

/// Scrubbing from the ruler. Playback stops for the duration of the drag —
/// seeking under a running player fights the rate observer — and the time is
/// pushed straight at the controller, never at an op: the playhead is view
/// state (spec §5.2). What is heard meanwhile is not the player but short
/// grains of the mix at the playhead (`ScrubAudio`, spec §11 AU-132).
struct PlayheadSession {
    var time: Ticks
    /// Everything a drag should stick to: 0, the end of the timeline, every
    /// marker, and the start and end of every clip except the ones in
    /// `exclude` (the clips being dragged — a clip must not snap to
    /// itself).
    ///
    /// Returns `{"ticks": [sorted unique ticks], "labels": {"<tick>": "…"}}`.
    /// `labels` is what the timeline shows in the snap indicator; when
    /// several things land on one tick the FIRST to claim it wins, and the
    /// insertion order below is that priority: the timeline bounds, then
    /// markers (a user placed them deliberately), then clip edges.
    ///
    /// The playhead and the in/out points are NOT here: they are view
    /// state, live in Swift, and Swift appends them to the array before
    /// calling [`resolve`].
    pub fn snap_candidates(&self, exclude: &[u32]) -> Value {
        let mut ticks: Vec<Ticks> = Vec::new();
        let mut labels: Map<String, Value> = Map::new();

        let mut add = |tick: Ticks, label: String, ticks: &mut Vec<Ticks>| {
            ticks.push(tick);
            labels
                .entry(tick.to_string())
                .or_insert(Value::String(label));
        };

        add(0, "start".to_string(), &mut ticks);
        add(self.duration(), "end".to_string(), &mut ticks);

        for marker in &self.markers {
            let label = if marker.name.is_empty() {
                "marker".to_string()
            } else {
                format!("marker: {}", marker.name)
            };
            add(marker.time, label, &mut ticks);
        }

        for clip in &self.clips {
            if exclude.contains(&clip.id) {
                continue;
            }
            add(clip.start, format!("clip {} start", clip.id), &mut ticks);
            add(
                clip.start.saturating_add(clip.duration),
                format!("clip {} end", clip.id),
                &mut ticks,
            );
        }

        ticks.sort_unstable();
        ticks.dedup();
    let total_ms = div_round_half_away(magnitude, TIMESCALE as i128 / 1000);
    let sign = sign_of(total_ms);
    let ms = total_ms % 1000;
    let total_seconds = total_ms / 1000;
    let ss = total_seconds % 60;
    let mm = (total_seconds / 60) % 60;
    let hh = total_seconds / 3600;
    format!("{sign}{hh:02}:{mm:02}:{ss:02}.{ms:03}")
}

/// Parses `"HH:MM:SS:FF"`, `"HH:MM:SS.mmm"`, `"HH:MM:SS"`, `"MM:SS"`,
/// `"SS.sss"` and a bare number of seconds, with an optional leading `-`.
/// The result is snapped to the frame grid. `None` when the text is not a
/// time (which is how the toolbar's timecode field rejects typing).
pub fn parse_timecode(s: &str, fps: Fps) -> Option<Ticks> {
    let text = s.trim();
    let (negative, body) = match text.strip_prefix('-') {
        Some(rest) => (true, rest.trim_start()),
        None => (false, text),
    };
    if body.is_empty() {
        return None;
    }

    let parts: Vec<&str> = body.split(':').collect();
    if parts.len() > 4 || parts.iter().any(|part| part.is_empty()) {
        return None;
    }

    let ticks: i128 = match parts.as_slice() {
        // Frames form. Only the last field may name frames, and none of the
        // fields may carry a fraction — "00:00:01:12.5" is not a timecode.
        [hh, mm, ss, ff] => {
            let nominal = fps.nominal()?;
            let hours = parse_digits(hh)?;
            let minutes = parse_digits(mm)?;
            let seconds = parse_digits(ss)?;
            let frames = parse_digits(ff)?;
            let whole = hours
                .checked_mul(3600)?
                .checked_add(minutes.checked_mul(60)?)?;
            let index = whole
                .checked_add(seconds)?
                .checked_mul(i128::from(nominal))?;
            let index = index.checked_add(frames)?;
            i128::from(tick_at_frame(clamp_ticks(index), fps)?)
        }
        [hh, mm, ss] => {
            let hours = parse_digits(hh)?;
            let minutes = parse_digits(mm)?;
            hours
                .checked_mul(3600 * TIMESCALE as i128)?
                .checked_add(minutes.checked_mul(60 * TIMESCALE as i128)?)?
                .checked_add(seconds_field_to_ticks(ss)?)?
        }
        [mm, ss] => {
            let minutes = parse_digits(mm)?;
            minutes
                .checked_mul(60 * TIMESCALE as i128)?
                .checked_add(seconds_field_to_ticks(ss)?)?
        }
        [ss] => seconds_field_to_ticks(ss)?,
        _ => return None,
    };

    let signed = if negative { -ticks } else { ticks };
    Some(snap_to_frame(clamp_ticks(signed), fps))
}

