    static func fitZoom(duration: Ticks, width: CGFloat) -> CGFloat {
        let seconds = Double(max(duration, ReelTime.perSecond)) / Double(ReelTime.perSecond)
        let usable = Double(max(width - headerWidth - 24, 80))
